def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])

    # The full-length 2 line is the divider.
    vertical = next((c for c in range(w) if all(grid[r][c] == 2 for r in range(h))), None)
    if vertical is None:
        return out

    from collections import Counter
    counts = Counter(v for row in grid for v in row)
    background = counts.most_common(1)[0][0]
    colors = [v for v in counts if v not in (background, 2)]
    if not colors:
        return out
    color = max(colors, key=lambda v: counts[v])
    cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
    if not cells:
        return out

    min_c = min(c for r, c in cells)
    max_c = max(c for r, c in cells)

    if max_c < vertical:
        shift = vertical - 1 - max_c
        marker = min_c + shift - 1
    elif min_c > vertical:
        shift = vertical + 1 - min_c
        marker = max_c + shift + 1
    else:
        return out

    for r, c in cells:
        out[r][c] = background
    for r, c in cells:
        nc = c + shift
        if 0 <= nc < w:
            out[r][nc] = color

    if 0 <= marker < w:
        for r in range(h):
            out[r][marker] = 8
    return out
